3	import type { EventType, TelemetryEvent } from './types.ts';
4	
5	interface UpgradeSummary {
6	  timestamp: number;
7	  eventType?: EventType;
8	  eventId?: string;
9	  sessionId?: string;
10	}
11	
12	export interface CacheEntry {
13	  timestamp: number;
14	  body: TelemetryEvent;
15	}
