17	let processingPromise: Promise<void> = Promise.resolve();
18	
19	const setHelper = async (eventType: EventType, body: TelemetryEvent) => {
20	  const lastEvents = (await cache.get('lastEvents')) || {};
21	  lastEvents[eventType] = { body, timestamp: Date.now() };
22	  await cache.set('lastEvents', lastEvents);
23	};
24	
25	export const set = (eventType: EventType, body: TelemetryEvent): Promise<void> => {
26	  const run = processingPromise.then(async () => {
27	    await setHelper(eventType, body);
28	  });
29	
30	  // Keep the chain alive even if this operation rejects, so later callers still queue
31	  processingPromise = run.catch(() => {});
32	
33	  return run;
34	};
35	
36	export const get = async (eventType: EventType): Promise<CacheEntry | undefined> => {
37	  const lastEvents = await getLastEvents();
38	  return lastEvents[eventType];
39	};
40	
41	export const getLastEvents = async (): Promise<Record<EventType, CacheEntry>> => {
42	  // Wait for any pending set operations to complete before reading
43	  await processingPromise;
44	  return (await cache.get('lastEvents')) || {};
45	};
46	
47	const upgradeFields = (event: CacheEntry): UpgradeSummary => {
48	  const { body, timestamp } = event;
49	  return {
50	    timestamp,
51	    eventType: body?.eventType,
52	    eventId: body?.eventId,
53	    sessionId: body?.sessionId,
54	  };
55	};
56	
57	const UPGRADE_EVENTS: EventType[] = ['init', 'upgrade'];
58	const RUN_EVENTS: EventType[] = ['build', 'dev', 'error'];
59	
60	const lastEvent = (lastEvents: Partial<Record<EventType, CacheEntry>>, eventTypes: EventType[]) => {
61	  const descendingEvents = eventTypes
62	    .map((eventType) => lastEvents?.[eventType])
63	    .filter((event): event is CacheEntry => Boolean(event))
64	    .sort((a, b) => b.timestamp - a.timestamp);
65	  return descendingEvents.length > 0 ? descendingEvents[0] : undefined;
66	};
67	
68	export const getPrecedingUpgrade = async (
69	  events: Partial<Record<EventType, CacheEntry>> | undefined = undefined
70	) => {
71	  const lastEvents =
72	    events || ((await cache.get('lastEvents')) as Partial<Record<EventType, CacheEntry>>) || {};
73	  const lastUpgradeEvent = lastEvent(lastEvents, UPGRADE_EVENTS);
74	  const lastRunEvent = lastEvent(lastEvents, RUN_EVENTS);
75	
76	  if (!lastUpgradeEvent) {
77	    return undefined;
78	  }
79	
80	  return !lastRunEvent?.timestamp || lastUpgradeEvent.timestamp > lastRunEvent.timestamp
81	    ? upgradeFields(lastUpgradeEvent)
82	    : undefined;
83	};
