87	 * occurrence of one of the given event types
88	 *
89	 * Used to gate telemetry that should only be captured during a single session window of a given event (e.g. init)
90	 */
91	export async function isWithinInitialSession(events: EventType | EventType[]): Promise<boolean> {
92	  try {
93	    const eventTypes = Array.isArray(events) ? events : [events];
94	    const lastEvents = await getLastEvents();
95	
96	    const lastRelevantEvent = lastEvent(lastEvents, eventTypes);
97	
98	    if (!lastRelevantEvent) {
99	      return false;
100	    }
101	
102	    const { getSessionId } = await import('./session-id.ts');
103	    const sessionId = await getSessionId();
104	
105	    // If the stored event carries a sessionId that differs from the current one the 2h window
106	    // has expired and a new session was started.
107	    if (lastRelevantEvent.body?.sessionId && lastRelevantEvent.body.sessionId !== sessionId) {
108	      return false;
109	    }
110	
111	    return true;
112	  } catch {
113	    return false;
114	  }
115	}
